MOD = 998244353

def closed_form(N, K):
    # E_K = (N+1)/2 - ((N-1)/2) * ((N-2)/N)^K
    return Fraction(N + 1, 2) - Fraction(N - 1, 2) * Fraction(N - 2, N) ** K

def markov(N, K):
    """Exact Markov chain: distribution of black ball position after K ops."""
    trans = [[Fraction(0)] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if i == j:
                trans[i][j] = 1 - Fraction(2 * (N - 1), N * N)
            else:
                trans[i][j] = Fraction(2, N * N)
    dist = [Fraction(0)] * N
    dist[0] = Fraction(1)
    for _ in range(K):
        nd = [Fraction(0)] * N
        for i in range(N):
            di = dist[i]
            if di:
                for j in range(N):
                    nd[j] += di * trans[i][j]
        dist = nd
    return sum((j + 1) * dist[j] for j in range(N))

# Cross-check closed form vs exact Markov chain for small N, various K
for N in range(1, 8):
    for K in [0, 1, 2, 3, 5, 10]:
        if K == 0:
            cf = Fraction(1)
        else:
            cf = closed_form(N, K)
        mv = markov(N, K) if K > 0 else Fraction(1)
        status = "OK " if cf == mv else "MISMATCH"
        if cf != mv:
