from fractions import Fraction

def closed_frac(N, K):
    return Fraction(N+1, 2) - Fraction(N-1, 2)*Fraction(N-2, N)**K

def sim_array(N, K, trials=30000):
    """Ground-truth simulation: physically maintain the row of balls."""
    total = 0
    for _ in range(trials):
        arr = [1] + [0]*(N-1)          # 1 = black
        for _ in range(K):
            a = random.randrange(N); b = random.randrange(N)
            if a != b:
                arr[a], arr[b] = arr[b], arr[a]
        total += arr.index(1) + 1
    return total / trials

def sim_index(N, K, trials=30000):
    """My earlier index-tracking simulation."""
    total = 0
    for _ in range(trials):
        pos = 1
        for _ in range(K):
            a = random.randrange(N); b = random.randrange(N)
            if a != b and (a == pos or b == pos):
                pos = b if a == pos else a
        total += pos + 1
    return total / trials

